sys_script_include.script:
(function transform(transformBuilder, transformScriptArgs) {
    try {
        if(!transformBuilder) return;
        var listModel = transformBuilder

        .transform();

        // Make comments column clickable
        listModel.columnDefinitions.columns.forEach(function(column) {
            if (column.key === 'comments') {
                // Force column to render as links
                column.type = 'url';
            }
        });

        // Update each cell
        listModel.rowDefinitions.rows.forEach(function(row) {
            var commentCell = row.cells['comments'];

            if (commentCell) {
                var commentValue = commentCell.value || '';
                var isEmpty = !commentValue || commentValue.trim() === '';

                // Set as URL type cell
                commentCell.type = 'url';

                if (isEmpty) {
                    commentCell.label = '+ Add comment';
                } else {
                    commentCell.label = commentValue;
                }

                // Use javascript:void(0) to make it clickable but not navigate
                commentCell.value = 'javascript:void(0)';
                commentCell.target = '_self';

                // Store original comment value in metadata
                if (!commentCell.metadata) {
                    commentCell.metadata = {};
                }
                commentCell.metadata.originalComment = commentValue;
                commentCell.metadata.isEmpty = isEmpty;
            }
        });

        return listModel;
    }
    catch(error) {
        return {
            failed: true,
            error: error.message
        };
    }
})(transformBuilder, transformScriptArgs);
